package testutils

import (
	"reflect"
	"strings"
	"testing"
	"time"

	fuzz "github.com/google/gofuzz"
	"github.com/stretchr/testify/assert"
)

// defaultFuzzIterations is the number of round-trip iterations performed when
// the caller does not override it via WithIterations.
const defaultFuzzIterations = 1000

// defaultNilChance is the probability that a nilable value is left nil during
// fuzzing when the caller does not override it via WithNilChance.
const defaultNilChance = 0.3

// FuzzOptions holds the configuration accumulated from the FuzzOption values
// passed to RunMapperFuzzTest.
type FuzzOptions struct {
	// customFuncs are extra gofuzz generator functions registered on top of the
	// built-in defaults. Later functions override earlier ones for the same type,
	// so these take precedence over the defaults.
	customFuncs []interface{}
	// excludedFields are additional struct field names that clearExcludedFields
	// should zero out before comparing the original and round-tripped values.
	excludedFields []string
	// nilChance is the probability that a nilable value is left nil.
	nilChance float64
	// iterations is the number of round-trip iterations to run.
	iterations int
}

// FuzzOption is a functional option for configuring RunMapperFuzzTest behavior.
type FuzzOption func(*FuzzOptions)

// WithCustomFuncs returns a FuzzOption that registers the provided custom gofuzz
// generator functions with the underlying fuzzer. Domain-specific helpers (for
// example enum fuzzers) are typically built on top of this option.
func WithCustomFuncs(funcs ...interface{}) FuzzOption {
	return func(o *FuzzOptions) {
		o.customFuncs = append(o.customFuncs, funcs...)
	}
}

// WithExcludedFields returns a FuzzOption that adds the given field names to the
// set of fields cleared before comparison. Fields whose names start with "XXX_",
// or that are named "sizeCache" or "unknownFields", are always cleared and do
// not need to be listed here.
func WithExcludedFields(fields ...string) FuzzOption {
	return func(o *FuzzOptions) {
		o.excludedFields = append(o.excludedFields, fields...)
	}
}

// WithNilChance returns a FuzzOption that sets the probability that a nilable
// value is left nil during fuzzing.
func WithNilChance(chance float64) FuzzOption {
	return func(o *FuzzOptions) {
		o.nilChance = chance
	}
}

// WithIterations returns a FuzzOption that sets the number of round-trip
// iterations RunMapperFuzzTest performs.
func WithIterations(iterations int) FuzzOption {
	return func(o *FuzzOptions) {
		o.iterations = iterations
	}
}

// defaultFuzzFuncs returns the gofuzz generator functions that are always
// applied. These cover time values (which lose monotonic clock readings,
// sub-nanosecond precision and location information when round-tripped through
// protobuf) so that comparisons after a round trip are meaningful.
func defaultFuzzFuncs() []interface{} {
	return []interface{}{
		func(t *time.Time, c fuzz.Continue) {
			if c.Intn(10) < 3 {
				*t = time.Time{}
				return
			}
			// A clean UTC time with no monotonic component, within a range that
			// survives conversion to and from protobuf timestamps.
