// RunMapperFuzzTest runs a round-trip fuzz test for a mapper pair. It fuzzes a
// value of TInternal, passes it through fromFunc and then toFunc, and asserts
// that the result equals the original. Protobuf-internal fields (and any fields
// named via WithExcludedFields) are stripped from both values before comparison.
func RunMapperFuzzTest[TInternal any, TExternal any](
	t *testing.T,
	fromFunc func(TInternal) TExternal,
	toFunc func(TExternal) TInternal,
	options ...FuzzOption,
) {
	t.Helper()

	opts := &FuzzOptions{
		nilChance:  defaultNilChance,
		iterations: defaultFuzzIterations,
	}
	for _, opt := range options {
		opt(opts)
	}

	seed := time.Now().UnixNano()
	t.Log("Fuzz Seed:", seed)

	f := fuzz.NewWithSeed(seed).NilChance(opts.nilChance)
	// Register defaults first, then custom funcs so custom funcs win for any
	// overlapping types.
	f = f.Funcs(defaultFuzzFuncs()...)
	if len(opts.customFuncs) > 0 {
		f = f.Funcs(opts.customFuncs...)
	}

	for i := 0; i < opts.iterations; i++ {
		var orig TInternal
		f.Fuzz(&orig)

		result := toFunc(fromFunc(orig))

		clearExcludedFields(&orig, opts.excludedFields)
		clearExcludedFields(&result, opts.excludedFields)

