			return // stop on first failure to avoid noisy output
		}
	}
}

// clearExcludedFields recursively traverses a struct (dereferencing through any
// number of pointer levels) and zeroes out fields whose names start with "XXX_",
// are named "sizeCache" or "unknownFields", or are listed in excludedFields.
// Nested value-type structs and slices (of both value and pointer elements) are
// processed in place. Fields that do not match the exclusion criteria are left
// untouched.
func clearExcludedFields(obj interface{}, excludedFields []string) {
	if obj == nil {
		return
	}
	clearExcludedFieldsValue(reflect.ValueOf(obj), excludedFields)
}

func clearExcludedFieldsValue(v reflect.Value, excludedFields []string) {
	// Dereference through any number of pointer / interface levels.
	for v.Kind() == reflect.Ptr || v.Kind() == reflect.Interface {
